"""Independent brute-force reference implementation of PROTOCOL.md (set-based)."""
import itertools, operator

OPS = {'eq': operator.eq, 'ne': operator.ne, 'lt': operator.lt, 'le': operator.le,
       'gt': operator.gt, 'ge': operator.ge}


def bf_compile_job(job):
    fields = job['fields']
    names = [f['name'] for f in fields]
    idx = {n: i for i, n in enumerate(names)}
    doms = [list(f['domain']) for f in fields]
    K = job['slots']
    nf = len(fields)
    cells = K * nf
    cell_field = [i for _ in range(K) for i in range(nf)]
    universe = list(itertools.product(*[doms[cf] for cf in cell_field]))
    U = len(universe)

    def cpos(ref):
        return ref[0] * nf + idx[ref[1]]

    def tval(term, w):
        if 'const' in term:
            return term['const']
        if 'sum' in term:
            return sum(w[cpos(r)] for r in term['sum'])
        if 'scale' in term:
            return term['scale'] * w[cpos(term['ref'])]
        return w[cpos(term['ref'])]

    preds = job['predicates']
    train = [tuple(itertools.chain.from_iterable(w)) for w in job['train']]
    width = job['width']

    uni_sets = []
    train_sets = []
    for p in preds:
        us = set()
        for u, w in enumerate(universe):
            if _ev(p, w, cpos, tval, OPS, idx, K, nf):
                us.add(u)
        ts = set()
        for r, w in enumerate(train):
            if _ev(p, w, cpos, tval, OPS, idx, K, nf):
                ts.add(r)
        uni_sets.append(us)
        train_sets.append(ts)

    all_train = set(range(len(train)))
    rules = []
    for length in range(1, width + 1):
        for clause in itertools.combinations(range(len(preds)), length):
            covered = set()
            for i in clause:
                covered |= train_sets[i]
            if covered != all_train:
                continue
            minimal = True
            for i in range(length):
                rest = set()
                for j in clause:
                    if j != clause[i]:
                        rest |= train_sets[j]
                if rest == all_train:
                    minimal = False
                    break
            if not minimal:
                continue
            truth = set()
            for i in clause:
                truth |= uni_sets[i]
            missing = set(range(U)) - truth
            if not missing:
                continue
            witnesses = []
            for i in range(length):
                others = set()
                for j in clause:
                    if j != clause[i]:
                        others |= train_sets[j]
                candidates = train_sets[clause[i]] - others
                witnesses.append(min(candidates) if candidates else None)
            rules.append({'clause': list(clause), 'witnesses': witnesses,
                          'counterexample': min(missing)})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]
    active_sets = []
    for clause in active:
        s = set()
        for i in clause:
            s |= uni_sets[i]
        active_sets.append(s)

    answers = []
    for q in job['queries']:
        target_pos = cpos(q['target'])
        prefix = q['prefix']
        fixed = {cpos(b['ref']): b['value'] for b in q['fixed']}
        count = 0
        witness = None
        chars = set()
        end = False
        for u, w in enumerate(universe):
            if any(w[p] != v for p, v in fixed.items()):
                continue
            if not all(u in s for s in active_sets):
                continue
            spelling = str(w[target_pos])
            if not spelling.startswith(prefix):
                continue
            count += 1
            if witness is None:
                witness = u
            if spelling == prefix:
                end = True
            elif len(spelling) > len(prefix):
                chars.add(spelling[len(prefix)])
        tokens = [d for d in '0123456789' if d in chars]
        if end:
            tokens.append('END')
        answers.append({'count': count, 'tokens': tokens,
                        'witness': witness if witness is not None else None})
    return {'rules': rules, 'active': active, 'answers': answers}


def _ev(p, w, cpos, tval, OPS, idx, K, nf):
    if p['kind'] == 'cmp':
        return OPS[p['op']](tval(p['left'], w), tval(p['right'], w))
    fi = idx[p['field']]
    op = OPS[p['op']]
    res = [op(w[slot * nf + fi], p['value']) for slot in range(K)]
    return any(res) if p['kind'] == 'any' else all(res)
PYEOF
